int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int ret = 0;
    unsigned char *src = from;
    unsigned char *dst = to;
    unsigned char *end = to + tolen;

    while (src < from + fromlen && dst < end) {
        unsigned char type = *src++;
        unsigned char len = *src++;

        if (type == 0) { /* current directory */
            *dst++ = '.';
            continue;
        } else if (type == 1) { /* parent directory */
            *dst++ = '.';
            if (dst < end) {
                *dst++ = '.';
            } else {
                ret = -ENAMETOOLONG;
                break;
            }
            continue;
        } else if (type == 2) { /* symlink */
            if (len > from + fromlen - src) {
                ret = -EINVAL;
                break;
            }
            if (dst + len > end) {
                ret = -ENAMETOOLONG;
                break;
            }
            for (int i = 0; i < len; i++) {
                *dst++ = *src++;
            }
            continue;
        } else {
            ret = -EINVAL;
            break;
        }
    }

    if (dst < end) {
        *dst = '\0';
    } else {
        ret = -ENAMETOOLONG;
    }

    return ret;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    while (i < fromlen && j < tolen - 1) {
        switch (from[i]) {
            case 0:
                to[j++] = '.';
                i++;
                break;
            case 1:
                to[j++] = '.';
                to[j++] = '.';
                i++;
                break;
            case 2:
                i++;
                if (i + 1 > fromlen)
                    return -EINVAL;
                to[j++] = from[i];
                i++;
                break;
            default:
                to[j++] = from[i];
                i++;
                break;
        }
    }

    if (i < fromlen)
        return -ERANGE;

    to[j] = '\0';

    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int offset = 0;
    int i = 0;

    if (!from || !to) {
        return -EINVAL;
    }

    while (i < fromlen) {
        if (offset >= tolen - 1) {
            return -ENAMETOOLONG;
        }

        if (from[i] == 0) {
            // Current directory
            to[offset++] = '.';
            i++;
        } else if (from[i] == 1) {
            // Parent directory
            if (offset + 2 > tolen - 1) {
                return -ENAMETOOLONG;
            }
            to[offset++] = '.';
            to[offset++] = '.';
            i++;
        } else if (from[i] == 2) {
            // Symlink
            i++;
            if (i + 1 > fromlen) {
                return -EINVAL;
            }
            int len = from[i];
            if (offset + len > tolen - 1) {
                return -ENAMETOOLONG;
            }
            memcpy(to + offset, from + i + 1, len);
            offset += len;
            i += 2 + len;
        } else {
            // Unknown component type
            return -EINVAL;
        }
    }

    to[offset] = '\0';
    return 0;
}

int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;
    int len = 0;

    if (!from || !to) {
        return -EINVAL;
    }

    if (tolen <= 0) {
        return -ENAMETOOLONG;
    }

    while (i < fromlen && j < tolen - 1) {
        unsigned char type = from[i];

        if (type == 0) {
            from += 2;
            i += 2;
            continue;
        }

        if (i + 1 > fromlen) {
            return -EINVAL;
        }

        int n = from[i + 1];

        if (type == 1) {
            if (n > fromlen - i - 2) {
                return -EINVAL;
            }

            if (j + n >= tolen) {
                return -ENAMETOOLONG;
            }

            for (int k = 0; k < n; k++) {
                to[j++] = from[i + 2 + k];
            }

            i += 2 + n;
        } else if (type == 2) {
            to[j++] = '.';
            i += 2;
        } else if (type == 3) {
            if (j + 2 >= tolen) {
                return -ENAMETOOLONG;
            }
            to[j++] = '.';
            to[j++] = '.';
            i += 2;
        } else if (type == 4) {
            if (j + 1 >= tolen) {
                return -ENAMETOOLONG;
            }
            to[j++] = '@';
            i += 2;
        } else if (type == 5) {
            if (n > fromlen - i - 2) {
                return -EINVAL;
            }

            if (j + 1 >= tolen) {
                return -ENAMETOOLONG;
            }

            for (int k = 0; k < n; k++) {
                to[j++] = from[i + 2 + k];
            }

            i += 2 + n;
        } else {
            return -EINVAL;
        }
    }

    if (j >= tolen) {
        return -ENAMETOOLONG;
    }

    to[j] = '\0';
    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int pos = 0;
    int i = 0;

    while (i < fromlen && pos < tolen - 1) {
        unsigned char type = from[i];

        switch (type) {
            case 0:  // Current directory
                to[pos++] = '.';
                break;
            case 1:  // Parent directory
                to[pos++] = '.';
                if (pos < tolen - 1) {
                    to[pos++] = '.';
                } else {
                    return -ENAMETOOLONG;
                }
                break;
            case 2:  // Symlink
                i++;
                if (i >= fromlen) {
                    return -EINVAL;
                }
                // Copy the symlink name directly
                while (i < fromlen && pos < tolen - 1) {
                    to[pos++] = from[i++];
                }
                break;
            default:  // Unknown type
                return -EINVAL;
        }

        i++;
    }

    // Null-terminate the output string
    if (pos < tolen) {
        to[pos] = '\0';
    } else {
        return -ENAMETOOLONG;
    }

    return 0;
}
